from .refs import CITE as R

SH = F.shot


def S(name, caption, base=5.6, max_h=3.9):
    """Screenshot figure with a width that keeps the picture on one page."""
    return FIG(SH(name), caption, F.shot_w(SH(name), base, max_h))


def TALL(name, caption):
    return FIG(SH(name), caption, F.shot_w(SH(name), 5.0, 6.6))


def _probe_title(prefix):
    """Title of the probe abstract whose 'title text' string starts with prefix (the metrics file keeps only 70 characters)."""
    try:
        from scripts.eval_data import PROBE

        for t, x, _ in PROBE:
            if f"{t} {x}".startswith(prefix[:60]):
                return t
    except Exception:  # noqa: BLE001
        pass
    return prefix[:50]


def _short(name):
    return name.replace("Reviewer ", "")


def _ms(v):
    return f"{v / 1000:.1f} s" if v >= 1000 else f"{v:.0f} ms"


