def _decision():
    sh, pc = F.SHIPPED, F.PER_CLASS
    cm = sh["confusion_matrix"]
    rows = [[k.replace("_", " "), v] for k, v in (("accuracy", F.f4(sh["accuracy"])), ("macro precision", F.f4(sh["precision_macro"])), ("macro recall", F.f4(sh["recall_macro"])),
                                                   ("macro F1", F.f4(sh["f1_macro"])), ("ROC-AUC (one-vs-rest, macro)", F.f4(sh["roc_auc"])))]
    b = F.BASELINES
    brow = [["Majority class (always borderline)", F.f3(b["majority_class"]["accuracy"]), F.f3(b["majority_class"]["f1_macro"]), "-"],
            ["Naive Bayes, word TF-IDF", F.f3(b["naive_bayes_word_tfidf"]["accuracy"]), F.f3(b["naive_bayes_word_tfidf"]["f1_macro"]), F.f3(b["naive_bayes_word_tfidf"]["roc_auc"])],
            ["Logistic regression, unweighted, word + char", F.f3(b["logreg_unweighted_word_char"]["accuracy"]), F.f3(b["logreg_unweighted_word_char"]["f1_macro"]), F.f3(b["logreg_unweighted_word_char"]["roc_auc"])],
            ["Logistic regression, balanced, word only", F.f3(b["logreg_balanced_word_only"]["accuracy"]), F.f3(b["logreg_balanced_word_only"]["f1_macro"]), F.f3(b["logreg_balanced_word_only"]["roc_auc"])],
            ["**PeerScope: logistic regression, balanced, word + char**", F.f3(sh["accuracy"]), F.f3(sh["f1_macro"]), F.f3(sh["roc_auc"])]]
    runs = F.SEEDS["runs"]
    srows = [[str(r["seed"]), F.f3(r["accuracy"]), F.f3(r["f1_macro"]), F.f3(r["roc_auc"])] for r in runs]
    srows.append(["**mean +/- sd**", f"{F.SEEDS['accuracy']['mean']:.3f} +/- {F.SEEDS['accuracy']['sd']:.3f}", f"{F.SEEDS['f1_macro']['mean']:.3f} +/- {F.SEEDS['f1_macro']['sd']:.3f}", f"{F.SEEDS['roc_auc']['mean']:.3f} +/- {F.SEEDS['roc_auc']['sd']:.3f}"])
    trows = [[f"{r['threshold']:.1f}", F.pct(r["coverage"]), str(r["n"]), (F.pct(r["accuracy_on_kept"]) if r["accuracy_on_kept"] is not None else "-")] for r in F.THR]
    g = F.GEN
    d = F.DM["decisive_only"]
    br = F.DM["borderline_row"]
    return [
        H2("8.3 Decision-model performance"),
        P(f"The decision model is a TF-IDF (word 1-2 grams and character 3-5 grams) and logistic-regression classifier with three classes. It was trained on the {F.DM['rows']:,}-row synthetic corpus and evaluated on {F.DM['test']} held-out papers. "
          "The first thing to say about the results is what the data is: the dataset was generated by a script that draws a hidden quality value, attaches three strength or weakness phrases to the text accordingly, and assigns the label from the same value. "
          "The result can therefore show that the pipeline trains, stores and serves a classifier; it cannot show that the classifier predicts real editorial decisions."),
        TAB("Metrics of the shipped model on the 280 held-out papers", ["Metric", "Value"], rows, widths=[3.4, 1.6], align=["l", "c"], size=10.5),
        TAB("Confusion matrix (rows true class, columns predicted class)", ["True \\ predicted", "accept", "borderline", "reject", "Support"],
            [[lab, *[str(x) for x in cm[i]], str(sum(cm[i]))] for i, lab in enumerate(F.DM["labels"])], widths=[1.6, 1.0, 1.1, 1.0, 1.0], align=["l", "c", "c", "c", "c"], size=10.5),
        FIG(F.fig("f01_confusion_matrix.png"), "Confusion matrix of the shipped model on 280 held-out papers (counts and row percentages).", 3.9),
        TAB("Per-class precision, recall and F1", ["Class", "Precision", "Recall", "F1", "Support"],
            [[k, F.f3(v["precision"]), F.f3(v["recall"]), F.f3(v["f1"]), str(v["support"])] for k, v in pc.items()], widths=[1.6, 1.1, 1.1, 1.1, 1.1], align=["l", "c", "c", "c", "c"], size=10.5),
        FIG(F.fig("f02_per_class.png"), "Precision, recall and F1 per class: accept and reject are found, borderline is not.", 5.0),
        H3("8.3.1 Reading the result"),
        P(f"The model finds almost every accept paper (recall {F.f3(pc['accept']['recall'])}) and almost every reject paper (recall {F.f3(pc['reject']['recall'])}), but only {F.DM['borderline_row']['predicted_borderline']} of the {pc['borderline']['support']} borderline papers "
          f"(recall {F.f3(pc['borderline']['recall'])}). Of the {pc['borderline']['support']} borderline papers, {br['predicted_accept']} were called accept and {br['predicted_reject']} reject. If only the decisive classes are considered, "
          f"{d['correct']} of {d['n']} accept and reject papers are classified correctly ({F.pct(d['accuracy'])}). The weakness is therefore concentrated in one class, and the data explains why."),
        P(f"In the synthetic corpus a paper whose text carries strength phrases is accept in {g['strong_phrase_papers']['label_counts']['accept']} cases and borderline in {g['strong_phrase_papers']['label_counts']['borderline']}; a paper with weakness phrases is reject in "
          f"{g['weak_phrase_papers']['label_counts']['reject']} cases and borderline in {g['weak_phrase_papers']['label_counts']['borderline']}. The text of a borderline paper is identical in kind to that of an accept or a reject paper, so no text-based rule can separate them. "
          f"The best accuracy any rule can reach from the phrases is {F.f3(g['best_possible_accuracy_from_phrases'])}, and the measured {F.f3(sh['accuracy'])} is close to that ceiling. The balanced class weights buy macro recall ({F.f3(sh['recall_macro'])}) at the price of some accuracy, as the unweighted variant below shows."),
        FIG(F.fig("f06_dataset_structure.png"), "Class counts of the synthetic dataset and how each label relates to the strength or weakness phrases in the text.", 5.6),
        TAB("Comparison with simple baselines on the same split", ["Model", "Accuracy", "Macro F1", "ROC-AUC"], brow, widths=[3.6, 0.9, 0.9, 0.9], align=["l", "c", "c", "c"], size=10),
        FIG(F.fig("f03_baselines.png"), "The shipped model against four baselines; the dashed line is the ceiling set by the construction of the labels.", 5.4),
        P(f"Against baselines the shipped configuration is clearly better than the majority class (accuracy {F.f3(b['majority_class']['accuracy'])}) and Naive Bayes ({F.f3(b['naive_bayes_word_tfidf']['accuracy'])}), and is statistically indistinguishable from the unweighted and word-only variants: "
          f"their accuracies ({F.f3(b['logreg_unweighted_word_char']['accuracy'])} and {F.f3(b['logreg_balanced_word_only']['accuracy'])}) differ by less than one standard deviation of the five-split study. The character n-grams add nothing measurable on this data, and the model kept them only because the design decision was taken before the result was known."),
        TAB("Five different train/test splits (same model configuration)", ["Split seed", "Accuracy", "Macro F1", "ROC-AUC"], srows, widths=[1.4, 1.5, 1.5, 1.5], align=["c", "c", "c", "c"], size=10.5),
        FIG(F.fig("f04_seed_study.png"), "Accuracy, macro F1 and ROC-AUC on five different splits.", 5.0),
        P(f"The headline split (seed 42, accuracy {F.f3(sh['accuracy'])}) is typical: over five splits accuracy ranges from {F.f3(F.SEEDS['accuracy']['min'])} to {F.f3(F.SEEDS['accuracy']['max'])}, a spread of about {F.pct(F.SEEDS['accuracy']['max'] - F.SEEDS['accuracy']['min'])} points. "
          "Differences below roughly three points between configurations should not be read as improvements."),
        TAB("Confidence threshold: papers kept and accuracy on them", ["Minimum confidence", "Papers kept", "n", "Accuracy on kept papers"], trows, widths=[1.5, 1.4, 0.8, 2.0], align=["c", "c", "c", "c"], size=10.5),
        FIG(F.fig("f05_threshold.png"), "Share of papers kept and accuracy on the kept papers as the minimum confidence rises.", 4.8),
        P(f"The probabilities are not very confident: at a threshold of 0.7 only {F.pct(F.thr_row(0.7)['coverage'])} of the papers remain and accuracy on them rises to {F.pct(F.thr_row(0.7)['accuracy_on_kept'])}; at 0.8 only {F.thr_row(0.8)['n']} papers remain. "
          "The application does not use a threshold; it shows the three class probabilities and states that the signal is one input among several."),
    ]


def _matching():
    mm, tf = F.MINILM, F.TFIDF
    names = [("full_hybrid_shipped_weights", "Hybrid, shipped weights"), ("semantic_similarity_only", "Semantic similarity only"),
             ("lexical_only_keyword_and_method", "Keyword and method overlap only"), ("hybrid_without_availability", "Hybrid without availability")]
    rows = [[lab, F.f3(mm[k]["top1"]), F.f3(mm[k]["top3"]), F.f3(mm[k]["mrr"]), F.f3(tf[k]["top1"]), F.f3(tf[k]["top3"]), F.f3(tf[k]["mrr"])] for k, lab in names]
    rows.append(["Random ranking (expectation)", F.f3(mm["random_expectation_top1"]), F.f3(mm["random_expectation_top3"]), "-", F.f3(tf["random_expectation_top1"]), F.f3(tf["random_expectation_top3"]), "-"])
    areas = list(mm["per_area_top1"].keys())
    arows = [[a.replace("Reviewer ", "") if a != "cross-area" else "cross-area (2 acceptable)", f"{mm['per_area_top1'][a]['correct']} / {mm['per_area_top1'][a]['n']}", f"{tf['per_area_top1'][a]['correct']} / {tf['per_area_top1'][a]['n']}"] for a in areas]
    miss = [[_probe_title(m["title"]), " or ".join(_short(x) for x in m["expected"]), _short(m["got"]), f"{m['expected_score']} vs {m['top_score']}"] for m in mm["top1_misses_shipped"]]
    n_tf_miss = len(tf["top1_misses_shipped"])
    srows = [[str(a["pool"]), _ms(a["median_ms"]), _ms(b["median_ms"])] for a, b in zip(mm["scaling_ms"], tf["scaling_ms"])]
    return [
        H2("8.4 Reviewer-matching results"),
        P("Reviewer matching was evaluated on the 40-abstract probe set described in Section 8.1: six topic areas with six abstracts each, plus four cross-area abstracts for which either of two reviewers is acceptable. "
          "For each abstract the full ranking of the six demo reviewers was produced by the production code, with no conflict text added, and the position of the best acceptable reviewer was recorded. "
          "Top-1 is the share of abstracts for which an acceptable reviewer is ranked first, top-3 the share for which one is in the first three, and MRR the mean reciprocal rank of the best acceptable reviewer. "
          "The labels were written by the project team and the abstracts avoid copying the reviewers' keyword lists, but the evaluation is still small and not independent; it measures whether the machinery behaves sensibly, not how it would perform on real submissions."),
        TAB("Matching quality on 40 probe abstracts", ["Configuration", "MiniLM top-1", "top-3", "MRR", "TF-IDF top-1", "top-3", "MRR"], rows,
            widths=[2.1, 0.8, 0.6, 0.6, 0.8, 0.6, 0.6], align=["l", "c", "c", "c", "c", "c", "c"], size=9.5),
        FIG(F.fig("f07_matching_configs.png"), "Top-1, top-3 and MRR of four score configurations with MiniLM embeddings (left) and the offline TF-IDF fallback (right); the dotted line is the random top-1 expectation.", 5.8),
        P(f"With sentence embeddings the shipped hybrid score ranks an acceptable reviewer first for {F.pct(mm['full_hybrid_shipped_weights']['top1'], 1)} of the abstracts (MRR {F.f3(mm['full_hybrid_shipped_weights']['mrr'])}), against a random expectation of {F.pct(mm['random_expectation_top1'], 1)}. "
          f"Semantic similarity alone is marginally better ({F.pct(mm['semantic_similarity_only']['top1'], 1)} top-1): the keyword, method and availability terms do not improve the ranking on this probe set; their purpose is auditability and the handling of load, not accuracy. "
          f"The keyword and method overlap on its own reaches {F.pct(mm['lexical_only_keyword_and_method']['top1'], 1)}: on these abstracts, which are short and use varied vocabulary, a dense encoder is clearly stronger than lexical overlap; in the base paper the relative merit of lexical and dense measures depends on the text view that is matched [{R['base']}]. "
          f"Removing availability changes the result by at most one abstract ({F.pct(mm['hybrid_without_availability']['top1'], 1)} top-1 with MiniLM)."),
        P(f"The offline fallback is clearly worse: {F.pct(tf['full_hybrid_shipped_weights']['top1'], 1)} top-1 and {F.pct(tf['full_hybrid_shipped_weights']['top3'], 1)} top-3 for the shipped weights. The fallback vectoriser is fitted once on the texts of the first request and then frozen, "
          "so its vocabulary reflects whichever paper was analysed first; the probe set reproduces that behaviour by ranking the 40 abstracts in sequence."),
        TAB("Top-1 hits per area (shipped hybrid score)", ["Area of the abstract (acceptable reviewer)", "MiniLM", "TF-IDF fallback"], arows, widths=[3.2, 1.3, 1.6], align=["l", "c", "c"], size=10.5),
        P(f"With MiniLM five areas are matched perfectly and the cross-area cases three out of four. The two misses are shown below. In both, the generalist Reviewer Gamma (applied machine learning and statistics) outscored the security specialist: abstracts on malware classifiers and on learning-based intrusion detection "
          f"use machine-learning vocabulary heavily and security vocabulary lightly. With the TF-IDF fallback there are {n_tf_miss} top-1 misses, concentrated in the vision and security areas (three of six each)."),
        TAB("Probe abstracts for which the shipped hybrid score (MiniLM) did not rank an acceptable reviewer first", ["Probe abstract", "Acceptable", "Ranked first", "Score: acceptable vs first"], miss,
            widths=[2.6, 1.2, 1.0, 1.6], align=["l", "c", "c", "c"], size=10),
        FIG(F.fig("f12_score_breakdown.png"), "Weighted contributions to the match score of the five active reviewers for the demo paper (3 pages, retrieval-grounded text classification).", 5.0),
        P(f"Mean gap between the first- and second-ranked reviewer is {mm['mean_gap_rank1_rank2']:.1f} points with MiniLM (about {tf['mean_gap_rank1_rank2']:.1f} with the fallback), so rankings are usually decisive on the probe set, but not on real papers outside the demo pool: the ReViewGraph paper obtained a top score of only 28.4 and a tie between two reviewers (Section 8.10)."),
        H3("8.4.1 Cost of ranking"),
        TAB("Median time to rank one paper against a growing reviewer pool", ["Reviewers in the directory", "MiniLM embeddings", "TF-IDF fallback"], srows, widths=[2.2, 2.0, 2.0], align=["c", "c", "c"], size=10.5),
        FIG(F.fig("f09_matching_scaling.png"), "Median ranking time against the number of reviewers (the pool is replicated from the six demo profiles).", 4.6),
        P(f"Ranking time grows linearly with the pool because every reviewer profile is embedded again for each request: {_ms(mm['scaling_ms'][0]['median_ms'])} for the six demo reviewers, {_ms(mm['scaling_ms'][1]['median_ms'])} for 50, {_ms(mm['scaling_ms'][2]['median_ms'])} for 200 and {_ms(mm['scaling_ms'][3]['median_ms'])} for 500. "
          "That is acceptable next to the minutes spent on the language model, but a cache of profile vectors would be the first change for a larger directory (Chapter 10)."),
    ]


def _conflict():
    c = F.MINILM["conflict"]
    det = c["detected_by_kind"]
    lit = [("conflict term", "A reviewer's conflict term appears in the text"), ("affiliation", "The reviewer's affiliation string appears in the text"), ("full name", "The reviewer's full name appears in the text"),
           ("paraphrased affiliation", "The affiliation is reworded (\"Computing Institute at Northbridge\")"), ("first name only", "Only the reviewer's first name is mentioned")]
    rows = [[k, d, f"{det[k]['detected']} / {det[k]['n']}"] for k, d in lit]
    inj = c["injected"]
    ex = [x for x in inj if x["detected"]][:3]
    exrows = [[x["reviewer"].replace("Reviewer ", ""), x["kind"], str(x["rank_before"]), str(x["rank_after"]), f"{x['score_before']} to {x['score_after']}"] for x in ex]
    miss = [x for x in inj if not x["detected"]]
    return [
        H2("8.5 Conflict-of-interest results"),
        P("Conflict handling was tested by injection. One sentence containing a known link was appended to a probe abstract, the six reviewers were ranked again and the flag, score and rank of the linked reviewer were compared with the clean ranking. "
          "Fifteen injections were made: six conflict terms, four affiliations, two full names and three links the matcher cannot see because they are paraphrased. In addition, all 40 clean probe abstracts were ranked against all six reviewers and the flags counted (240 pairs)."),
        TAB("Conflict detection by kind of link", ["Kind of injected link", "What was written", "Detected"], rows, widths=[1.7, 3.6, 1.0], align=["l", "l", "c"], size=10.5),
        FIG(F.fig("f08_conflict_detection.png"), "Conflict detection by kind of link: literal strings are found, paraphrases are missed.", 4.8),
        P(f"All twelve literal links were flagged and none of the three paraphrased ones was. The false-flag count on clean papers is {c['false_flags_on_clean_papers']} of {c['clean_pairs_checked']} pairs. When a link is flagged, the penalty of 0.60 is subtracted before scaling, so the score of a flagged reviewer falls to zero in every injected case and the reviewer drops to the last rank; "
          "the card then shows \"Penalized\" with the reason and the instruction to verify before assigning."),
        TAB("Effect of a flagged conflict on a reviewer's rank and score (examples)", ["Reviewer", "Kind", "Rank before", "Rank after", "Score"], exrows, widths=[1.1, 1.4, 1.0, 1.0, 1.7], align=["l", "l", "c", "c", "c"], size=10.5),
        P("These results describe a literal matcher doing what it was designed to do. They do not describe conflict-of-interest detection in the sense of the base paper's setting, where co-authorship, shared funding and institutional ties are the relevant relations and are not visible as strings in the submission. "
          f"The three misses ({', '.join(m['kind'] for m in miss)}) show the gap; a co-author graph and normalised affiliations are listed as future work."),
    ]


def _real():
    rows = []
    names = ["Demo fixture (3 pages)", "Survey, arXiv 2604.27924", "ReViewGraph, arXiv 2511.08317", "IEEE Access base paper"]
    for n, r in zip(names, F.REAL):
        rows.append([n, str(r["pages"]), f"{r['words']:,}", str(len(r["sections_detected"])), str(r["references_detected"]), F.f2(r["structural_score"]),
                     f"{r['ml_label']} ({r['ml_confidence']:.2f})", r["title_extracted"][:44]])
    lat = [[n, F.f2(r["structure_completeness"]), F.f2(r["evidence_coverage"]), F.f2(r["method_clarity"]), F.f2(r["presentation"]), F.f2(r["structural_score"])] for n, r in zip(["Demo fixture", "Survey", "ReViewGraph", "IEEE base paper"], F.REAL)]
    return [
        H2("8.6 The pipeline on real papers"),
        P("Four PDFs were run through the same code as an uploaded file: the three-page demo fixture generated by `scripts/make_demo_pdf.py` and three real research papers kept with the batch, the base paper [1], the survey [6] and the ReViewGraph paper [7]. "
          "No ground truth exists for these files, so the table reports what the pipeline extracted and what it concluded, not whether it was right."),
        TAB("Extraction and signals on four PDFs", ["File", "Pages", "Words", "Sections found", "Refs found", "Structural", "Decision signal", "Title extracted"], rows,
            widths=[1.35, 0.45, 0.6, 0.6, 0.5, 0.65, 0.95, 1.4], align=["l", "c", "c", "c", "c", "c", "c", "l"], size=8.5),
        TAB("Components of the structural score", ["Paper", "Structure completeness", "Evidence coverage", "Method clarity", "Presentation", "Overall"], lat,
            widths=[1.4, 1.2, 1.1, 1.0, 1.0, 0.8], align=["l", "c", "c", "c", "c", "c"], size=10),
        FIG(F.fig("f10_real_papers_signals.png"), "Structural signals on four real PDFs.", 5.4),
        P("Four observations follow. First, extraction works on text-based academic PDFs of 17 to 30 pages in under half a second after the library is loaded. "
          "Second, the structural score varies little (65.2 to 75.9) because three of its four components saturate for any normal paper; the evidence component, which depends on references per page, is the one that moves (17.3 to 50.3). "
          "Third, the extraction is not robust to layout conventions: the base paper from IEEE Access uses roman-numeral headings, so its introduction is not detected (six of nine sections found), and its title heuristic returns the \"Digital Object Identifier\" line. "
          f"Fourth, the decision model returned \"borderline\" for all four papers with confidences between {min(r['ml_confidence'] for r in F.REAL):.2f} and {max(r['ml_confidence'] for r in F.REAL):.2f}. "
          "A classifier trained on templated synthetic sentences has no basis for judging real manuscripts, and the output is what that implies; the interface presents it as a weak signal for this reason."),
    ]


def _latency():
    L = F.LATENCY
    st = L["pipeline_stages"]
    d, s = st["demo"], st["survey_30_pages"]
    keys = ["PDF extraction", "Feature extraction", "Decision signal", "Local AI review (3 steps)", "Literature (OpenAlex)", "Reviewer matching"]
    rows = [[k, _ms(d[k]), _ms(s[k])] for k in keys] + [["**Total**", _ms(d["_total_ms"]), _ms(s["_total_ms"])]]
    h = L["http_api"]
    hrows = [["GET /api/health", "40", _ms(h["health"]["median_ms"]), _ms(h["health"]["p95_ms"])],
             ["GET /api/reviewers", "40", _ms(h["reviewers_list"]["median_ms"]), _ms(h["reviewers_list"]["p95_ms"])],
             ["GET /api/model/metrics", "40", _ms(h["model_metrics"]["median_ms"]), _ms(h["model_metrics"]["p95_ms"])],
             ["GET /api/analyses", "40", _ms(h["analyses_list"]["median_ms"]), _ms(h["analyses_list"]["p95_ms"])],
             ["POST /api/analyze, 3-page PDF, AI review off", str(h["analyze_demo_3_pages"]["n"]), _ms(h["analyze_demo_3_pages"]["median_ms"]), f"max {_ms(h['analyze_demo_3_pages']['max_ms'])}"],
             ["POST /api/analyze, 30-page PDF, AI review off", str(h["analyze_survey_30_pages"]["n"]), _ms(h["analyze_survey_30_pages"]["median_ms"]), f"max {_ms(h['analyze_survey_30_pages']['max_ms'])}"],
             ["GET export, PDF report", "1", _ms(h["export_pdf"]["median_ms"]), f"{h['export_pdf']['bytes']:,} bytes"],
             ["GET export, JSON", "1", _ms(h["export_json"]["median_ms"]), f"{h['export_json']['bytes']:,} bytes"]]
    on = L["http_llm_on_s"]
    share = d["Local AI review (3 steps)"] / d["_total_ms"]
    return [
        H2("8.7 Performance and latency"),
        P("Latency was measured in two ways: stage by stage in one process (the model files already cached on disk), and over HTTP on 127.0.0.1 against a running server. "
          "The local address matters: on this machine `localhost` adds about two seconds per call through an IPv6 fallback, which would hide the real figures."),
        TAB("Time per pipeline stage (one analysis, local language model on)", ["Stage", "Demo paper, 3 pages", "Survey, 30 pages"], rows, widths=[2.8, 1.8, 1.8], align=["l", "c", "c"], size=10.5),
        FIG(F.fig("f11_pipeline_timings.png"), "Where the time goes in one analysis of the demo paper on the CPU.", 5.2),
        P(f"The local language model takes {F.pct(share)} of the time of an analysis: {_ms(d['Local AI review (3 steps)'])} for three generation calls producing {d['_ai_tokens_all_steps']:,} tokens, about {d['_ai_tokens_all_steps'] / (d['Local AI review (3 steps)'] / 1000):.1f} tokens per second. "
          f"Everything else together takes {_ms(d['_total_ms'] - d['Local AI review (3 steps)'])}. The first PDF extraction of a process is slower ({_ms(d['PDF extraction'])}) because the PDF library is imported lazily; later extractions of a 30-page paper take {_ms(s['PDF extraction'])}. "
          f"Loading the encoder took {L['embedding_model_load_s']:.1f} s and the language model {L['llm_load_s']:.1f} s once, from the local cache, in the measuring process. "
          f"Through the server, with a cold process, the complete analysis took {on['ieee_base_paper_30_pages']} s for the base paper and {on['arxiv_survey_30_pages']} s for the survey, and {on['reviewgraph_17_pages_via_browser']} s when driven through the browser while Chrome was rendering."),
        TAB("HTTP latency on 127.0.0.1 (local model switched off for the analyze rows)", ["Request", "Calls", "Median", "95th percentile / extra"], hrows, widths=[3.1, 0.6, 1.0, 1.7], align=["l", "c", "c", "c"], size=10),
        P("With the language model switched off the whole analysis of a 3-page or 30-page paper takes about 1.2 to 1.3 seconds over HTTP, of which the OpenAlex lookup is the largest part; simple reads take a few milliseconds. "
          "The application is therefore interactive in its deterministic mode and a background job in its full mode. No job queue exists in the code, and two simultaneous full analyses would compete for the same cores."),
    ]


